-- Initial PostgreSQL foundation for clean installations.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE,display_name text,avatar_url text,preferred_language text NOT NULL DEFAULT 'dari',role text NOT NULL DEFAULT 'user' CHECK(role IN ('user','admin')),status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','deleted')),password_hash text,default_model text,email_verified boolean NOT NULL DEFAULT false,memory_enabled boolean NOT NULL DEFAULT true,preferences_json jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS auth_identities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,provider text NOT NULL,provider_subject text NOT NULL,email_verified boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(provider,provider_subject));
CREATE TABLE IF NOT EXISTS sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),last_seen_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS sessions_user_id_idx ON sessions(user_id);
CREATE INDEX IF NOT EXISTS sessions_expires_at_idx ON sessions(expires_at);
CREATE TABLE IF NOT EXISTS conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,title text NOT NULL DEFAULT 'New chat',model text,provider text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),archived_at timestamptz);
CREATE INDEX IF NOT EXISTS conversations_user_updated_idx ON conversations(user_id,updated_at DESC);
CREATE TABLE IF NOT EXISTS messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,role text NOT NULL CHECK(role IN ('system','user','assistant','tool')),content text NOT NULL,model text,token_input integer,token_output integer,status text NOT NULL DEFAULT 'complete' CHECK(status IN ('pending','complete','failed')),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS messages_conversation_created_idx ON messages(conversation_id,created_at);
CREATE TABLE IF NOT EXISTS provider_configs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),provider_key text NOT NULL UNIQUE,display_name text NOT NULL,enabled boolean NOT NULL DEFAULT false,default_model text,config_json jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS model_catalog(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),provider_key text NOT NULL,model_key text NOT NULL,display_name text NOT NULL,capabilities text[] NOT NULL DEFAULT ARRAY['chat'],enabled boolean NOT NULL DEFAULT true,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,context_window integer NOT NULL DEFAULT 0,verified_at timestamptz,last_health_ok boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(provider_key,model_key));
CREATE TABLE IF NOT EXISTS usage_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id) ON DELETE SET NULL,provider_key text NOT NULL,model_key text,capability text NOT NULL DEFAULT 'chat',input_tokens integer NOT NULL DEFAULT 0,output_tokens integer NOT NULL DEFAULT 0,cost_microusd bigint NOT NULL DEFAULT 0,request_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS generated_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,asset_type text NOT NULL,prompt text,storage_key text NOT NULL,mime_type text,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS email_verification_codes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,purpose text NOT NULL CHECK(purpose IN ('verify_email','password_reset')),code_hash text NOT NULL,expires_at timestamptz NOT NULL,consumed_at timestamptz,attempts integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS user_preferences(user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,language text NOT NULL DEFAULT 'dari',appearance text NOT NULL DEFAULT 'system',accent_color text NOT NULL DEFAULT 'cyan',density text NOT NULL DEFAULT 'comfortable',font_size integer NOT NULL DEFAULT 14,chat_width text NOT NULL DEFAULT 'comfortable',animations_enabled boolean NOT NULL DEFAULT true,default_model text,auto_select_model boolean NOT NULL DEFAULT true,response_style text NOT NULL DEFAULT 'balanced',response_length text NOT NULL DEFAULT 'medium',creativity numeric(3,2) NOT NULL DEFAULT 0.70,memory_enabled boolean NOT NULL DEFAULT true,voice_enabled boolean NOT NULL DEFAULT true,default_language text NOT NULL DEFAULT 'dari',notifications_json jsonb NOT NULL DEFAULT '{}'::jsonb,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS user_memories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,category text NOT NULL,content text NOT NULL,consent_sensitive boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS productivity_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,tool_type text NOT NULL,title text NOT NULL,content text NOT NULL DEFAULT '',parameters jsonb NOT NULL DEFAULT '{}'::jsonb,is_pinned boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS user_notification_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,event_type text NOT NULL,title text NOT NULL,body text NOT NULL DEFAULT '',read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs(id bigserial PRIMARY KEY,actor_user_id uuid REFERENCES users(id) ON DELETE SET NULL,action text NOT NULL,target_type text,target_id text,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS feature_flags(flag_key text PRIMARY KEY,enabled boolean NOT NULL DEFAULT false,description text NOT NULL DEFAULT '',updated_by uuid REFERENCES users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rate_limit_policies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),scope_type text NOT NULL,scope_key text NOT NULL,requests integer NOT NULL,window_seconds integer NOT NULL,enabled boolean NOT NULL DEFAULT true,updated_by uuid REFERENCES users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(scope_type,scope_key));
CREATE TABLE IF NOT EXISTS security_events(id bigserial PRIMARY KEY,event_type text NOT NULL,severity text NOT NULL DEFAULT 'info',user_id uuid REFERENCES users(id) ON DELETE SET NULL,request_id text,ip_hash text,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS admin_request_events(id bigserial PRIMARY KEY,request_id text NOT NULL,method text NOT NULL,route text NOT NULL,status_code integer NOT NULL,duration_ms integer NOT NULL DEFAULT 0,classification text NOT NULL DEFAULT 'success',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rate_limit_counters(scope_type text NOT NULL,scope_key text NOT NULL,window_start timestamptz NOT NULL,request_count integer NOT NULL DEFAULT 0,PRIMARY KEY(scope_type,scope_key,window_start));
CREATE TABLE IF NOT EXISTS provider_fallback_chains(capability text PRIMARY KEY,ordered_models jsonb NOT NULL DEFAULT '[]'::jsonb,updated_by uuid REFERENCES users(id) ON DELETE SET NULL,updated_at timestamptz NOT NULL DEFAULT now());
